responses.text:
{
  "instrument": "Directive (EU) 2023/2673 — Shopify Help Center",
  "jurisdiction": "EU",
  "summary": "Enable the two-step withdrawal function in your checkout settings before 19 June 2026 if you sell to EU customers. This Shopify help page describes the EU withdrawal function required by the amended Consumer Rights Directive.",
  "effective_dates": [
    "2026-06-19"
  ],
  "obligations": [
    {
      "text": "Offer a withdrawal function so customers can cancel in two steps.",
      "quote": "stores that sell to customers in the European Union need to offer a withdrawal function so customers can cancel a contract in two steps"
    }
  ]
}
